import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, inviteAndJoin, waitForWorkspaceReady } from './helpers';

// Fresh 2-node game: pageA is white (node 0, host), pageB is black (node 1).
async function startNewGame(pageA: import('@playwright/test').Page, pageB: import('@playwright/test').Page) {
  await inviteAndJoin(pageA, pageB);
  await expect(pageA.getByTestId('action-create_game')).toBeVisible({ timeout: 15_000 });
  await pageA.getByTestId('action-create_game').click();
  await expect(pageA.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
  await expect(pageB.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
}

test.describe(`player: place a piece to preview my move locally`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`previewing a move only updates the player's own local (non-persisted) board state and is never written to shared CRDT state`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    // White previews e2-e4 locally — only the local board re-renders.
    await pageA.getByTestId('square-e2').click();
    await pageA.getByTestId('square-e4').click();
    await expect(pageA.getByTestId('square-e4')).toContainText('♙');
    await expect(pageA.getByTestId('square-e2')).not.toContainText('♙');

    // Reload: the preview was never written to shared CRDT state, so it
    // vanishes and the original starting position (from get_game_state)
    // reappears — proof it was purely local, non-persisted state.
    await pageA.reload();
    await waitForWorkspaceReady(pageA);
    await expect(pageA.getByTestId('square-e2')).toContainText('♙', { timeout: 10_000 });
    await expect(pageA.getByTestId('square-e4')).not.toContainText('♙');

    await ctxA.close();
    await ctxB.close();
  });

  test(`the opponent's board is unaffected by any local preview`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    // White previews e2-e4 locally.
    await pageA.getByTestId('square-e2').click();
    await pageA.getByTestId('square-e4').click();
    await expect(pageA.getByTestId('square-e4')).toContainText('♙');

    // The opponent's board is untouched by the preview — still the original
    // starting position.
    await expect(pageB.getByTestId('square-e2')).toContainText('♙');
    await expect(pageB.getByTestId('square-e4')).not.toContainText('♙');

    await ctxA.close();
    await ctxB.close();
  });
});
